export const ANALYSIS_USE_CASE_PRESETS = COMMAND_WORKSPACE_USE_CASE_PRESETS.map((preset) => ({
  code: preset.code,
  title: preset.title,
  summary: preset.summary,
  missionMode: preset.missionMode,
  audience: preset.audience,
  timeHorizon: preset.timeHorizon,
  reportTemplate: preset.reportTemplate,
  decisionQuestion: preset.decisionQuestion,
  policyQuestion: preset.policyQuestion,
  successMetrics: preset.successMetrics,
  constraints: preset.constraints,
  materials: preset.materials,
  guide: preset.guide,
}))

export function buildCreateFormFromPreset(preset) {
  return {
    name: preset?.roomName || '',
    description: preset?.description || '',
    classificationLevel: preset?.classificationLevel || 'confidential',
    commandScope: preset?.commandScope || '',
  }
}

export function buildLaunchFormFromPreset(preset, previous = {}) {
  return {
    mission_mode: preset?.missionMode || previous.mission_mode || 'war_ground_rehearsal',
    audience: preset?.audience || previous.audience || 'staff_officer',
    classification_level: previous.classification_level || 'confidential',
    time_horizon: preset?.timeHorizon || previous.time_horizon || '72h',
    report_template: preset?.reportTemplate || previous.report_template || 'WarGroundDecisionCard',
    decision_question: preset?.decisionQuestion || '',
    policy_question: preset?.policyQuestion || '',
    success_metrics: preset?.successMetrics || '',
    constraints: preset?.constraints || '',
  }
}

export function detectUseCasePreset(source = '') {
  const normalized = normalizeText(source)
  if (!normalized) return null

  return COMMAND_WORKSPACE_USE_CASE_PRESETS.find((preset) =>
    preset.markers.some((marker) => normalized.includes(normalizeText(marker))),
  ) || null
}
